#include <bits/stdc++.h>
#define TEMP template<typename T>
#define TEMP2<typename T, typename... Args>
#define REG register
#define INT_REG register int
#define CONST_REF const&
#define INLINE_FUNC inline
#define LOOP while
#define MAX_LIMIT 1000000
#define MOD_CONST1 998244353
#define MOD_CONST2 1000000007
#define LL_TYPE long long
#define Dec(x) (!(x--)&&(x+=MOD_CONST2))
using namespace std;

LL total_num, max_num, counter_var;
int answer_val, digit_count_arr[7], count_arrs[7][7], sum_data[7][7][MAX_LIMIT+1];

void setup(int x, int depth, const_ref int& max_depth) {
    sum_data[max_depth][depth][++count_arrs[max_depth][depth]] = (++counter_var) - x;
    if (depth == max_depth) return;
    for (int i = 0; i <= 9; ++i) setup(x * 10 + i, depth + 1, max_depth);
}

void brute_force(long long x, int depth) {
    if (x > total_num) return;
    ++counter_var;
    answer_val = (answer_val + (counter_var - x) / MOD_CONST1 - (counter_var < x) + MOD_CONST2) % MOD_CONST2;
    for (int i = 0; i <= 9; ++i) brute_force(x * 10 + i, depth + 1);
}

void process_num(int x, int depth) {
    if (depth != 6) {
        ++counter_var;
        answer_val = (answer_val + (counter_var - x) / MOD_CONST1 - (counter_var < x) + MOD_CONST2) % MOD_CONST2;
        for (int i = 0; i <= 9; ++i) process_num(x * 10 + i, depth + 1);
        return;
    }
    if (x == max_num) return brute_force(x, 0);
    int k; long long v;
    for (k = 0, v = x; k <= 6 && v <= total_num; ++k, v *= 10);
    --k;
    for (int i = 0; i <= k; ++i) {
        v = counter_var - 1LL * x * digit_count_arr[i];
        answer_val = (answer_val + 1LL * (v / MOD_CONST1 - (v < 0) + MOD_CONST2) * digit_count_arr[i]) % MOD_CONST2;
        v = (v % MOD_CONST1 + MOD_CONST1) % MOD_CONST1;
        answer_val = (answer_val + digit_count_arr[i] - (lower_bound(sum_data[k][i] + 1, sum_data[k][i] + digit_count_arr[i] + 1, v) - sum_data[k][i]) + 1) % MOD_CONST2;
    }
    for (int i = 0; i <= k; ++i) counter_var += digit_count_arr[i];
}

int main() {
    int i, k, d;
    scanf("%lld", &total_num);
    digit_count_arr[0] = i = 1;
    for (k = 1; k <= 6; ++k) digit_count_arr[k] = digit_count_arr[k - 1] * 10;
    for (k = 0; k <= 6; ++k) {
        counter_var = 0;
        setup(0, 0, k);
        for (i = 0; i <= k; ++i) sort(sum_data[k][i] + 1, sum_data[k][i] + digit_count_arr[i] + 1);
    }
    counter_var = 0;
    if (counter_var == 0 && total_num < 1e6) {
        for (i = 1; i <= 9; ++i) brute_force(i, 1);
    } else {
        max_num = total_num;
        while (max_num >= 1e6) max_num /= 10;
        for (i = 1; i <= 9; ++i) process_num(i, 1);
    }
    printf("%d\n", (int)((1LL * (MOD_CONST2 - answer_val) * MOD_CONST1) % MOD_CONST2));
    return 0;
}
